# file: main.tf
variable "ami_id" {
  type = string
}

variable "servers" {
  type = map(object({
    type = string
  }))
}

resource "aws_instance" "web" {
  for_each      = var.servers
  ami           = var.ami_id
  instance_type = each.value.type

  tags = {
    Name = each.key
  }
}

output "private_ips" {
  value = { for k, i in aws_instance.web : k => i.private_ip }
}
```

