# file: main.tf
variable "admin_cidr" {
  type        = string
  description = "CIDR block for admin access"
}

variable "app_sg_id" {
  type        = string
  description = "Security group ID of the application tier"
}

resource "aws_security_group" "db_access" {
  name   = "db-access"
  vpc_id = "vpc-0abc123"

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    cidr_blocks     = [var.admin_cidr]
  }

  ingress {
    from_port       = 3306
    to_port         = 3306
    protocol        = "tcp"
    security_groups = [var.app_sg_id]
  }

  tags = {
    Name = "db-access"
  }
}
